import { expect, test, uniqueName } from "../../fixtures";

test("vendor names are unique within a tenant", { tag: "@VEN-03" }, async ({ apiAs }) => {
  // Arrange: an existing vendor in the member's tenant
  const member = await apiAs("member");
  const name = uniqueName("Acme Freight");
  const created = await member.post("/api/vendors", {
    data: { name, category: "logistics", contact_email: "ops@acmefreight.example" },
  });
  expect(created.status(), await created.text()).toBe(201);

  // Act: create a vendor whose name differs only by case
  const res = await member.post("/api/vendors", {
    data: { name: name.toLowerCase(), category: "logistics", contact_email: "ops@acmefreight.example" },
  });

  // Assert
  const body = await res.text();
  expect(res.status(), body).toBe(409);
  expect(JSON.parse(body).error.code, body).toBe("vendor_name_taken");
});
